import{z as B,x as d,o,c as p,q as r,j as l,D as e,d as t,s as n,S as i,b as E}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"最小费用最大流","description":"","frontmatter":{"title":"最小费用最大流","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/min-cost-flow.md","filePath":"cs/min-cost-flow.md","lastUpdated":1791063341000}'),m={name:"cs/min-cost-flow.md"};function A(f,a,h,u,D,F){const s=d("Mermaid");return o(),p("div",null,[a[2]||(a[2]=r('<h1 id="最小费用最大流" tabindex="-1">最小费用最大流 <a class="header-anchor" href="#最小费用最大流" aria-label="Permalink to &quot;最小费用最大流&quot;">​</a></h1><div class="epigraph"><p>每条边既有容量又有费用；最大流中费用最小者，可由残量上对费用做最短路反复增广，或用消圈。</p><footer>—— 据 Klein, A Primal Method for Minimal Cost Flows, 1967；Edmonds and Karp, 1972；CLRS 第 26、29 章整理</footer></div><p>上一课<a href="/cs/boruvka-second-mst">Borůvka 与次小生成树</a>收束无向 MST。主干<a href="/cs/max-flow-ff">最大流</a>只有容量。缺口是<strong>费用</strong>：单位流经过边 \\(e\\) 付 \\(w(e)\\)，求最大流中总费用最小（或指定流量 \\(F\\) 的最小费用）。不重证最大流最小割。后课用最小割做建模，费用流当运输工具。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>流满足容量与守恒；费用 \\(\\sum_e w(e)f(e)\\)。残量：正向费用 \\(w\\)，反向 \\(-w\\)（退流退款）。连续最短路（SSP）：在残量上对 \\(w\\) 求 \\(s\\)–\\(t\\) 最短路（无负环时 Bellman–Ford 或势函数 + Dijkstra），沿路增广，直到流量够或无可增广。有负环则先消费用负圈（Klein）：残量负圈对应可改进费用而不改 \\(|f|\\)。</p><p><span class="marginnote">术语翻译：残量网络就是「把每条边还剩多少可走、倒着退要花什么」重画出来的图——正向边剩容量、费用记 \\(w\\)；反向边代表「把已送的流退回去」，费用记 \\(-w\\)。退货不但可行，还把原来那笔运费退给你。</span></p><p>缺口是「费用残量」，不是新的守恒定律。整数容量、有限最优时终止。</p><h3 id="势函数消去负边" tabindex="-1">势函数消去负边 <a class="header-anchor" href="#势函数消去负边" aria-label="Permalink to &quot;势函数消去负边&quot;">​</a></h3><p>\\(w\\) 可负（退流）。Johnson 势 \\(h\\)：\\(\\hat w(u,v)=w(u,v)+h(u)-h(v)\\ge 0\\) 后 Dijkstra。<a href="/cs/johnson-apsp">Johnson 全源</a>已用过这套；本课每次增广后更新势。不要对含负圈的残量跑 Dijkstra。</p><p><span class="marginnote">Klein 1967 消圈。Edmonds–Karp 也讨论最小费用。连续最短路是教材默认。容量缩放、消圈的多项式实现（Goldberg–Tarjan）点名不写。后课最小割建模常不需要费用。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>建残量。若可能有负圈，先消圈或用 Bellman–Ford 判。循环：最短路增广。记录流量与费用。二分图带权匹配可化成费用流（下一课的下一课 KM 是组合特例）。</p>',12)),(o(),l(i,null,{default:e(()=>[n(s,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E6%B5%81%20f%22%5D%20--%3E%20Gf%5B%22%E8%B4%B9%E7%94%A8%E6%AE%8B%E9%87%8F%22%5D%0A%20%20Gf%20--%3E%20SP%5B%22%E6%9C%80%E5%B0%8F%E8%B4%B9%E7%94%A8%20s%E2%80%93t%20%E8%B7%AF%22%5D%0A%20%20SP%20--%3E%20AUG%5B%22%E5%A2%9E%E5%B9%BF%22%5D%0A%20%20AUG%20--%3E%20F%0A%20%20Gf%20--%3E%20NC%5B%22%E8%B4%9F%E5%9C%88%EF%BC%9F%E6%B6%88%E5%9C%88%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"无源汇循环流的最小费用是纯消圈。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"最优性：可行流费用最小当且仅当残量无负费用圈。SSP 每步沿最小费用路加，保持「当前流量下费用最优」的不变式（需证明增广不破坏）。与普通最大流：忽略 \\(w\\) 则回到 Ford–Fulkerson，费用可能很差。",-1)),a[6]||(a[6]=E("p",null,[E("span",{class:"marginnote"},"数字实例：若残量里有圈 \\(a\\to b\\to c\\to a\\)，费用依次 \\(2+2-6=-2\\)，沿这个圈推 1 单位流：每个点进出各一次，守恒不破、流量 \\(|f|\\) 不变，总费用却省 2——这就是 Klein 消圈：见到负圈就说明当前流还不是最省的。")],-1)),a[7]||(a[7]=E("p",null,[E("span",{class:"marginnote"},"直觉类比：SSP 像「每次都挑当前最便宜的线路多送一件货」。每多送一件，网络就变了（容量耗尽、冒出反向边），所以每一步都要在最新残量图上重求最短路，而不是照旧地图一路送到黑。")],-1)),(o(),l(i,null,{default:e(()=>[n(s,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20OLD%5B%22%E7%AC%AC%E4%B8%80%E6%89%B9%E6%B5%81%E8%B5%B0%E4%BA%86%20s%E2%86%92a%E2%86%92t%2C%20%E6%AF%8F%E5%8D%95%E4%BD%8D%E8%B4%B9%E7%94%A8%2010%22%5D%20--%3E%20BETTER%5B%22%E5%90%8E%E6%9D%A5%E5%8F%91%E7%8E%B0%E7%BB%8F%20b%20%E7%9A%84%E8%B7%AF%E6%9B%B4%E4%BE%BF%E5%AE%9C%22%5D%0A%20%20BETTER%20--%3E%20REV%5B%22%E6%96%B0%E8%B7%AF%E5%BE%84%E7%94%A8%20a%E2%86%92b%20%E7%9A%84%E5%8F%8D%E5%90%91%E8%BE%B9%20b%E2%86%92a%2C%20%E8%B4%B9%E7%94%A8%E8%AE%B0%20-10%20%E9%80%80%E6%AC%BE%22%5D%0A%20%20REV%20--%3E%20UNDO%5B%22%E7%AD%89%E4%BA%8E%E6%8A%8A%20a%20%E9%82%A3%E4%BB%BD%E6%B5%81%E3%80%8E%E9%80%80%E3%80%8F%E5%9B%9E%E5%8E%BB%E6%94%B9%E9%81%93%22%5D%0A%20%20UNDO%20--%3E%20RESULT%5B%22%E6%80%BB%E6%B5%81%E9%87%8F%E4%B8%8D%E5%8F%98%2C%20%E6%80%BB%E8%B4%B9%E7%94%A8%E4%B8%8B%E9%99%8D%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=r('<p>运输、指派、带下界的流，都先化成这份网络。不要用 MST 的边权当流费用的算法。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写全部多项式算法的紧界，不写环流分解细节全文。负无穷容量或无界费用要先检查。后课默认：最小费用流 = 残量最短路增广或消圈。下一课把最大流最小割当成建模语言。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>费用残量：正向 \\(w\\)、反向 \\(-w\\)；无负圈则最优。</li><li>连续最短路增广；负边用势 + Dijkstra。</li><li>指派等问题先化网络。</li><li>出处：Klein, 1967；Edmonds and Karp, 1972；CLRS。</li></ul>',5))])}const b=B(m,[["render",A]]);export{T as __pageData,b as default};
